// ✅ one deferred import, no other path to the library, and a real load state
import 'admin/admin_page.dart' deferred as admin;

class AdminGate extends StatefulWidget {
  const AdminGate({super.key});
  @override
  State<AdminGate> createState() => _AdminGateState();
}

class _AdminGateState extends State<AdminGate> {
  Future<void> _load = admin.loadLibrary();

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<void>(
      future: _load,
      builder: (context, snap) {
        if (snap.hasError) {
          return ErrorRetry(
            // loadLibrary() is idempotent; calling it again retries the fetch
            onRetry: () => setState(() => _load = admin.loadLibrary()),
          );
        }
        if (snap.connectionState != ConnectionState.done) {
          return const Center(child: CircularProgressIndicator());
        }
        return admin.AdminPage(); // only legal after the future completes
      },
    );
  }
}

