final router = GoRouter(
  // Do NOT repeat the sub-path here: <base href> already strips /console/,
  // so routes stay root-relative and the same code works at the root.
  routes: [
    GoRoute(path: '/', builder: (_, __) => const HomeScreen()),
    GoRoute(path: '/settings/:id', builder: (c, s) => SettingsScreen(id: s.pathParameters['id']!)),
  ],
  redirect: (context, state) {
    // A host that 301s to or from a trailing slash delivers a URL you did not
    // route for; canonicalise instead of 404-ing on it.
    final path = state.uri.path;
    if (path.length > 1 && path.endsWith('/')) {
      return path.substring(0, path.length - 1);
    }
    return null;
  },
);

