class _LedgerAppState extends State<LedgerApp> {
  late final AppLifecycleListener _lifecycle;

  @override
  void initState() {
    super.initState();
    // Cmd+Q, the taskbar close and OS shutdown all arrive here
    _lifecycle = AppLifecycleListener(onExitRequested: _confirmQuit);
  }

  Future<AppExitResponse> _confirmQuit() async {
    if (!store.isDirty) return AppExitResponse.exit;
    final save = await showDialog<bool>(context: context, builder: _saveSheet);
    if (save == null) return AppExitResponse.cancel; // dismissed: stay open
    if (save) await store.save();
    return AppExitResponse.exit;
  }

  @override
  void dispose() {
    _lifecycle.dispose();
    super.dispose();
