// ✅ reading is portable as long as you ask for bytes, never a path
Future<String?> pickCsv() async {
  final XFile? file = await openFile(
    acceptedTypeGroups: const [XTypeGroup(label: 'csv', extensions: ['csv'])],
  );
  if (file == null) return null;
  // File(file.path) would work on desktop and fail on a blob: URL
  return utf8.decode(await file.readAsBytes());
}

// ✅ saving on the web: a Blob and a synthetic click, inside the same gesture
void downloadCsv(String csv, String name) {
  final blob = web.Blob(
    [csv.toJS].toJS,
    web.BlobPropertyBag(type: 'text/csv;charset=utf-8'),
  );
  final url = web.URL.createObjectURL(blob);
  (web.document.createElement('a') as web.HTMLAnchorElement)
    ..href = url
    ..download = name
    ..click();
  web.URL.revokeObjectURL(url);
}

