import 'dart:ui';
import 'package:flutter/foundation.dart';
import 'package:http/http.dart' as http;

// Both handlers, or half your release errors never reach the tracker
void installErrorHandlers(Tracker tracker) {
  FlutterError.onError = (details) {
    FlutterError.presentError(details);
    tracker.report(details.exception, details.stack); // map resolved server-side
  };
  PlatformDispatcher.instance.onError = (error, stack) {
    tracker.report(error, stack);
    return true;
  };
}

Future<String> load(Uri url, String token) async {
  try {
    final res = await http.get(url, headers: {'Authorization': 'Bearer $token'});
    return res.body;
  } on http.ClientException catch (e) {
    // "XMLHttpRequest error." with no status means the browser blocked it:
    // CORS, a mixed-content http:// call from an https:// page, or DNS.
    // The Authorization header alone forces an OPTIONS preflight that the
    // server must answer with Allow-Headers: authorization.
    if (kIsWeb) throw NetworkBlocked(url, e);
    rethrow;
  }
}

